import{At as e,mt as t,n,pt as r}from"./chunks/framework.BrKcMR_c.js";var i=JSON.parse(`{"title":"ADR-0067: Lead waits for the current action","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0067-lead-waits-for-the-current-action.md","filePath":"adrs/0067-lead-waits-for-the-current-action.md","lastUpdated":1789092097000}`),a={name:`adrs/0067-lead-waits-for-the-current-action.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0067-lead-waits-for-the-current-action" tabindex="-1">ADR-0067: Lead waits for the current action <a class="header-anchor" href="#adr-0067-lead-waits-for-the-current-action" aria-label="Permalink to “ADR-0067: Lead waits for the current action”">​</a></h1><p>Status: Accepted, 2026-09-08. Refines ADR-0066.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Lead dismissed a pending file-write approval, leaving an orange unexecuted-tool result. The user wants ordinary guidance to wait for the current step to finish, with Stop remaining the explicit interruption control.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Saving Lead never cancels an approval. The current model response and its first tool action can finish, including any approval, execution, and result persistence. The pending instruction is supplied before the next model response. If the current response contains multiple calls, apply Lead between actions and retain explicit unexecuted results for later calls from the old response.</p><p>Keep approvals authoritative: Allow executes the current action; Deny records a denial even if Lead is queued. Stop cancels the turn and pending approval as before. The composer says &quot;Lead queued • applies after the current action&quot; and its help explains that approvals stay open.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>A pending write is no longer skipped simply because the user provides guidance. Lead can wait for approval; users can deny that action or press Stop when they want to interrupt it. Durable saves, the single generation owner, and completion of in-flight writes remain unchanged.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>Waiting for the entire coding task would delay guidance indefinitely. Automatically approving a pending action would override the user&#39;s file-permission choice. Cancelling approvals on every Lead caused the reported skipped writes.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};